constructor(element?: string | Element | null, config?: Partial<DrawerConfig> | null) {
  super(element, config)
  this._swipeHelper = null
  this._resizeObserver = null
  this._resizeFrame = null
  this._initResizeObserver()

  // Focus the autofocus element when the drawer is shown
  EventHandler.on(this._element, 'shown.bs.drawer', () => {
    const autofocusElement = this._element.querySelector('[autofocus]')
    if (autofocusElement instanceof HTMLElement) {
      autofocusElement.focus()
    }
  })
}
